void aic_set_language(lang_type_t lang)
{
    if ((int)lang < 0 || (int)lang >= AIC_LANG_NUM) {
        LV_LOG_WARN("invalid lang %d, keep %d", (int)lang, (int)current_lang);
        return;
    }
    current_lang = lang;
}

/* 越界/空列一律返回空串，调用方无需判空（lv_label_set_text(NULL) 会崩） */
const char *aic_get_translation(key_id_t key)
{
    if ((int)key < 0 || (int)key >= KEY_ID_NUM)
        return "";
    if ((int)current_lang < 0 || (int)current_lang >= AIC_LANG_NUM)
        return "";
    const char *s = translations[key][current_lang];
    return s ? s : "";
}

const lv_font_t *aic_init_lang_font(int font_id, int font_size)
{
    const lv_font_t *font = aic_font_list_find(font_id, font_size);
    if (font)
        return font;

    char font_path[256] = {0};
    snprintf(font_path, sizeof(font_path) - 1, "%s/font/%s", LVGL_STORAGE_PATH, font_names[font_id]);

    font = ui_font_init(font_path, font_size);
    if (!font) {
        LV_LOG_ERROR("Failed to init font");
        return NULL;
    }

    aic_font_list_add(font_id, font_size, font);
    return font;
}

const lv_font_t *aic_get_lang_font(int font_id, int font_size, bool c_flag)
{
    if (c_flag)
        return aic_get_c_font(font_id, font_size);
    else
        return aic_init_lang_font(font_id, font_size);
}

const lv_font_t *aic_get_multi_lang_font(int font_size)
{
    const aic_language_t *lang = get_current_lang();
    return aic_get_lang_font(lang->font_id, font_size, lang->c_flag);
}

const lv_font_t *aic_get_c_font(int font_id, int font_size)
{
    switch (font_id) {
        case THAI_TTF:
            switch (font_size) {
                case 16:
                    return &c_thai_16;
                case 18:
                    return &c_thai_18;
                case 22:
                    return &c_thai_22;
                default:
                    /* 其余字号只渲染数字/单位等纯 ASCII，回退通用字体，
                     * 避免返回 NULL 导致 lv_obj_set_style_text_font(label, NULL) 丢字体 */
                    return aic_get_c_font(DEFAULT_TTF, font_size);
            }
        case SPEEDLABEL_TTF:
            switch (font_size) {
                case 32:
                    return &c_speedlabel_32;
                case 36:
                    return &c_speedlabel_36;
                case 90:
                    return &c_speedlabel_90;
                case 50:
                    return &c_speedlabel_50;
                default:
                    return NULL;
            }
        case DEFAULT_TTF:
            switch (font_size) {
                case 10:
                    return &c_default_10;
                case 11:
                    return &c_default_11;
                case 12:
                    return &c_default_12;
                case 16:
                    return &c_default_16;
                case 18:
                    return &c_default_18;
                case 22:
                    return &c_default_22;
                case 24:
                    return &c_default_24;
                case 36:
                    return &c_default_36;
                case 41:
                    return &c_default_41;

                default:
                    return NULL;
            }

        default:
            return NULL;
    }
}

const aic_language_t *get_current_lang()
{
    return &languages[current_lang];
}
